import sys
sys.setrecursionlimit(10**6)

def detect_cycle_dfs(graph, u, visited, parent):
    visited[u] = True
    for v in graph[u]:
        if not visited[v]:
            if detect_cycle_dfs(graph, v, visited, u):
                return True
        elif v != parent:
            return True
    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No Cycle")
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0 or m == 0:
        print("No Cycle")
        return

    graph = [[] for _ in range(n)]
    idx = 2
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            if detect_cycle_dfs(graph, i, visited, -1):
                print("Cycle Found")
                return

    print("No Cycle")

if __name__ == "__main__":
    main()
